def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    def tail_d(arr, k):
        m = k if k < n else n
        if m <= 0:
            return 0
        total = 0
        i = n - m
        while i < n:
            if arr[i] == 'D':
                total += 1
            i += 1
        return total

    totalD = tail_d(op, n)
    totalD_ratio = totalD / float(n)

    oppD4 = tail_d(op, 4)
    oppD6 = tail_d(op, 6)
    oppD10 = tail_d(op, 10)
    oppD12 = tail_d(op, 12)

    recent_window10 = min(n, 10)
    recent_op_c10 = recent_window10 - oppD10

    start = n - 12
    if start < 1:
        start = 1

    after_C_total = 0
    after_C_coop = 0
    for i in range(start, n):
        if me[i - 1] == 'C':
            after_C_total += 1
            if op[i] == 'C':
                after_C_coop += 1

    if after_C_total >= 4:
        after_C_rate = after_C_coop / float(after_C_total)
    else:
        if totalD_ratio <= 0.10:
            after_C_rate = 0.90
        elif totalD_ratio <= 0.30:
            after_C_rate = 0.70
        elif totalD_ratio <= 0.50:
            after_C_rate = 0.40
        else:
            after_C_rate = 0.15

    recent_all_D6 = n >= 6 and oppD6 == min(6, n) and recent_op_c10 == 0
    persistent_all_D = n >= 12 and oppD12 == 12

    forgiving = (after_C_rate >= 0.55 or recent_op_c10 >= 5 or totalD_ratio <= 0.40)
    if recent_all_D6:
        forgiving = False

    exploiter = (persistent_all_D or
                 (after_C_rate <= 0.30 and totalD_ratio >= 0.55 and recent_op_c10 <= 3))

    last_m = me[-1]
    last_o = op[-1]

    if last_m == 'C' and last_o == 'D':
        just_broke = False
        if n >= 2 and me[-2] == 'D' and op[-2] == 'D':
            just_broke = True

        if just_broke and forgiving and not exploiter:
            return 'C'

        if just_broke and not exploiter and recent_op_c10 >= 2:
            return 'C'

        if exploiter and n >= 3:
            return 'D'

        if oppD4 >= 2:
            return 'D'

        if oppD6 >= 3 and totalD_ratio > 0.18:
            return 'D'

        if totalD_ratio > 0.45:
            return 'D'

        return 'C'

    if last_m == 'D' and last_o == 'D':
        mutual_run = 0
        i = n - 1
        while i >= 0 and me[i] == 'D' and op[i] == 'D':
            mutual_run += 1
            i -= 1

        if forgiving:
            limit = 2
        elif exploiter:
            limit = 30
        elif oppD6 >= 5 and recent_op_c10 <= 1:
            limit = 12
        else:
            limit = 4

        if mutual_run >= limit and not (exploiter and oppD10 >= 9):
            return 'C'

        return 'D'

    return 'C'
